import { get, isNil } from 'lodash';

/**
 * @typedef {Object} columnDefinition
 * @property headerName {string} - the name of the header
 * @property generateCsvData {generateCsvData} - the callback to generate a csv value string
 */

/**
 * @typedef {Object} cellValueProps
 * @property rowData {array} - the row values to calculate the cells for a row
 * @property columnDefinition {columnDefinition} - the column definitions for the table
 * @property columnIndex {number} - the index value of the current column

/**
 *  getCellValue
 * @param {cellValueProps} cellValueProps -  object containing the props for the function
 * @returns {string} - the value to be added to a cell in a csv export
 */
export const getCellValue = ({
  rowData,
  columnDefinition,
  columnIndex,
  itemPath,
}) => {
  const nestedLevel = !isNil(itemPath) ? itemPath.length - 1 : null;
  const generatedCellValue = columnDefinition.generateCsvData({
    rowData,
    column: {
      definition: columnDefinition,
      index: columnIndex,
    },
    ...(nestedLevel && { nestedLevel }),
  });

  return generatedCellValue || '--';
};

/**
 * generateCsvData callback
 * @callback generateCsvData
 * @param {rowData} any - the data for the row for AGGrid
 * @param {column} object - the index and column definition for a column
 *
 * @return {string} The csv formatted string for a table cell
 */

/**
 * @typedef {Object} columnDefinition
 * @property headerName {string} - the name of the header
 * @property generateCsvData {generateCsvData} - the callback to generate a csv value string
 */

/**
 * @typedef {Object} downloadCsvProps
 * @property columnDefinition {Array.<columnDefinition>} - array containing column definitions for the table
 * @property csvFileName {string} - the name of the file to download including the .csv extension
 * @property rows {array} - the table data that is passed into AGGrid
 */

/**
 *  downloadAGGridCsv - downloads a csv file of the data for the table
 *
 * @param {downloadCsvProps} downloadCsvProps - object containing the props for the callback
 */
export const downloadAGGridCsv = ({
  columnFormatters,
  csvFileName,
  rows = [],
}) => {
  // Make sure filename includes the extension
  const fileName = csvFileName.endsWith('.csv')
    ? csvFileName
    : `${csvFileName}.csv`;

  const dataRows = Array.from({ length: rows.length }, () => []);
  const headerRow = columnFormatters.map((columnDefinition) => {
    const attemptColumns = get(columnDefinition, 'children');
    if (attemptColumns) {
      // There are multiple attempts
      return attemptColumns.map(
        (attemptColumn) =>
          `${columnDefinition.headerName} - ${attemptColumn.headerName}`,
      );
    }

    return columnDefinition.headerName;
  });

  rows.forEach((row, rowIndex) => {
    const { rowData, attemptRows, itemPath } = row;
    columnFormatters.forEach((columnDefinition, columnIndex) => {
      const attemptColumns = get(columnDefinition, 'children');
      if (attemptColumns) {
        // There are multiple attempts
        const listInstanceId = get(columnDefinition, [
          'props',
          'listInstanceId',
        ]);
        const attemptRowsData = get(attemptRows, listInstanceId);

        const attemptsRowCells = attemptColumns.map(
          (attemptColumnDefinition, attemptColumnIndex) => {
            const attemptRowData = get(attemptRowsData, [rowIndex, 'rowData']);

            return getCellValue({
              rowData: attemptRowData,
              columnDefinition: attemptColumnDefinition,
              columnIndex: attemptColumnIndex,
              itemPath,
            });
          },
        );

        dataRows[rowIndex][columnIndex] = attemptsRowCells;
      } else {
        const cellValue = getCellValue({
          rowData,
          columnDefinition,
          columnIndex,
          itemPath,
        });

        dataRows[rowIndex][columnIndex] = cellValue;
      }
    });
  });

  const csvRows = [headerRow, ...dataRows];

  let csvString = '';
  csvRows.forEach((rowArray) => {
    const preparedRows = rowArray.map((cell) => {
      // If there are multiple attempts, cell will be an array.
      cell = Array.isArray(cell) ? cell : [cell];
      cell = cell.map((item) => {
        if (
          typeof item === 'string' &&
          (item.includes(',') || item.includes('"') || item.includes('\n'))
        ) {
          return `"${item.replace(/"/g, '""')}"`;
        }

        return item;
      });

      return cell.join(',');
    });
    const row = preparedRows.join(',');
    csvString += `${row}\r\n`;
  });

  const link = document.createElement('a');
  link.setAttribute(
    'href',
    `data:text/csv;charset=utf-8,${encodeURIComponent(`\uFEFF${csvString}`)}`,
  );
  // Replace all period characters in filename with underscore, except file extension (LW-883, LW-4018)
  link.setAttribute('download', fileName.replace(/\.(?!csv$)/gi, '_'));
  document.body.appendChild(link);
  link.click();

  return csvString;
};
